### 5.1 Exports
export const isJoinableUrl = (url: string | null | undefined): url is string => { ... };
export const getJoinableConferenceUrl = (conference: GridEvent["conference"]): string | null => { ... };
- isJoinableUrl is a type predicate so getJoinableConferenceUrl narrows without a cast.
- getJoinableConferenceUrl body: const url = conference?.url; return isJoinableUrl(url) ? url : null;
- GridEvent["conference"] is `Conference | null | undefined`, so no separate @core import is needed.

### 5.2 isJoinableUrl implementation shape
if (!url) return false;
try {
  const { protocol } = new URL(url);
  return protocol === "http:" || protocol === "https:";
} catch {
  return false;
}

### 5.3 Behaviour table
| "https://meet.google.com/abc-defg-hij" | true |
| "http://meet.example.com/x" | true |
| "HTTPS://Meet.Example.com" | true |
| "javascript:alert(1)" | false |
| "data:text/html,<script>x</script>" | false |
| "vbscript:msgbox(1)" | false |
| "file:///etc/passwd" | false |
| "//meet.google.com/x" | false (new URL throws without a base) |
| "meet.google.com/x" | false (throws) |
| "" | false (short-circuits on !url) |
| null / undefined | false |

### 5.5 Return the original string, not the normalized one
getJoinableConferenceUrl returns conference.url UNCHANGED, never new URL(url).href. new URL("https://zoom.us").href is "https://zoom.us/"; normalizing would silently rewrite the provider's URL.

export const ConferenceSchema = z.strictObject({
  url: z.url(),
  label: z.string().trim().min(1).max(256).nullable(),
});
export type Conference = z.infer<typeof ConferenceSchema>;

import { darken } from "@web/common/styles/color.utils";
import { RepeatIcon } from "@web/components/Icons/Repeat";

interface Props {
  baseColor: string;
}

/**
 * The recurrence indicator shared by the timed and all-day grid cards: a small
 * repeat glyph pinned to the card's bottom-right, tinted a darker shade of the
 * event color so it complements the card instead of a loud fixed white.
 * Keeping it in one place stops the two cards from drifting apart.
 * Decorative — the recurring state is announced via each card's aria-label.
 */
export const EventRepeatIcon = ({ baseColor }: Props) => (
  <RepeatIcon
    aria-hidden="true"
    className="pointer-events-none absolute right-1 bottom-0.5"
    color={darken(baseColor, 30)}
    size={10}
    weight="bold"
  />
);

### 4.1 Props
interface Props {
  /** The card's resolved fill (bgColor), not the raw palette base. */
  baseColor: string;
  /** conference.label; null/absent falls back to "Join meeting". */
  label?: string | null;
  /** Already scheme-checked by the card; re-checked here (fail closed). */
  url: string;
}
Exported as a named const: export const EventJoinIcon = ({ baseColor, label, url }: Props) => {

### 4.2 Imports
import { VideoCameraIcon } from "@phosphor-icons/react";
import { ZIndex } from "@web/common/constants/web.constants";
import { darken } from "@web/common/styles/color.utils";
import { isJoinableUrl } from "./event-join-url.util";

### 4.3 Rendered element tree
<button type="button" aria-label={accessibleLabel} class=... style={{ zIndex: ZIndex.LAYER_5 }} ...handlers>
  <VideoCameraIcon aria-hidden="true" className="pointer-events-none" color={darken(baseColor, 30)} size={10} weight="bold" />
</button>

Exact classes on the <button>:
"absolute right-4.5 bottom-0.5 flex h-2.5 w-2.5 items-center justify-center rounded-xs focus-visible:outline focus-visible:outline-1 focus-visible:outline-offset-0 focus-visible:outline-(--event-focus-color)"

- --event-focus-color is already set as an inline CSS variable on both card roots, so the button inherits the card's focus chrome.
- style={{ zIndex: ZIndex.LAYER_5 }} — the timed card's bottom resize handle is LAYER_4 and overlaps the button's bottom ~2px.
- NO positioning class on the <svg>. Its class attribute is exactly "pointer-events-none".

### 4.4 Accessible name
const accessibleLabel = label ? `Join ${label}` : "Join meeting";

### 4.5 Fail-closed render guard
First statement in the component body, before any JSX:
if (!isJoinableUrl(url)) return null;
No hooks precede it, so there is no conditional-hook hazard.

### 4.6 Activation
const openConference = () => {
  if (!isJoinableUrl(url)) return;
  window.open(url, "_blank", "noopener,noreferrer");
};
The URL passed to window.open is the ORIGINAL provider string, not new URL(url).href.

### 4.7 Full handler set
onMouseDown: e.stopPropagation();   // cards drive drag/selection from mousedown, not click. No preventDefault - that would suppress focus.
onPointerDown: e.stopPropagation(); // defense in depth
onClick: e.stopPropagation(); openConference();   // no preventDefault needed; type="button"
onKeyDown: if (e.key !== "Enter" && e.key !== " ") return; e.stopPropagation(); e.preventDefault(); openConference();
  // stopPropagation stops the card's own Enter/Space handler; preventDefault suppresses the native button click-on-Enter so the link opens exactly once, and suppresses Space-scroll. Non-Enter/Space keys deliberately fall through.
Everything else (blur/focus/mouseenter/mouseleave) is left alone.
type="button" is mandatory and must be written explicitly.

### 4.8 TSDoc (required)
The one-click join affordance shared by the timed and all-day grid cards. It is a real <button> rather than part of the card's own click target because the card's mousedown starts a drag - a nested control with its own name is the only way to offer "join" without also meaning "select and drag this event". Sits one slot left of the repeat glyph and borrows its size/weight/tint so the two read as one icon family rather than two competing badges. The URL is re-checked here, not just at the call site, because conference.url is provider-sourced and a control that can be tricked into opening a javascript: URL is worse than no control.

