const createEvent = (overrides: Partial<GridEvent> = {}): GridEvent =>
  ({
    _id: "event-1",
    endDate: "2024-01-15T10:00:00.000Z",
    isAllDay: false,
    position: {
      dragOffset: { x: 0, y: 0 },
      horizontalOrder: 0,
      initialX: null,
      initialY: null,
      isOverlapping: false,
      totalEventsInGroup: 1,
      widthMultiplier: 1,
    },
    recurrence: undefined,
    startDate: "2024-01-15T09:00:00.000Z",
    title: "Planning block",
    ...overrides,
  }) as GridEvent;

const position = {
  height: 60,
  left: 10,
  top: 20,
  width: 140,
};

describe("EventCard", () => {
  afterEach(() => {
    useEdgeFocusStore.setState(initialEdgeFocusState, true);
  });

it("places the repeat indicator bottom-right", () => {
  const { container } = render(
    <TimedEventCard
      displayMode="saved"
      event={createEvent({
        recurrence: { eventId: "series-1", rule: ["RRULE:FREQ=WEEKLY"] },
      })}
      motionMode="idle"
      position={position}
    />,
  );
  const icon = container.querySelector('svg[class*="right-1"]');

  expect(icon).not.toBeNull();
  const iconClass = icon?.getAttribute("class") ?? "";
  expect(iconClass).not.toContain("left-1");
  expect(iconClass).not.toContain("text-muted");
});

it("keeps timed event keyboard activation from reaching parent shortcuts", () => {
  const onEventKeyDown = mock();
  const onParentKeyDown = mock();

  render(
    <div onKeyDown={onParentKeyDown}>
      <TimedEventCard
        displayMode="saved"
        event={createEvent()}
        motionMode="idle"
        onEventKeyDown={onEventKeyDown}
        position={position}
      />
    </div>,
  );

  fireEvent.keyDown(screen.getByRole("button"), { key: "Enter" });

  expect(onEventKeyDown).toHaveBeenCalledTimes(1);
  expect(onParentKeyDown).not.toHaveBeenCalled();
});

export interface AllDayEventCardProps {
  calendarIdentity?: CalendarCardIdentity | null;
  event: GridEvent;
  focusColor?: string | null;
  interactionAttributes?: Record<string, string | undefined>;
  isPlaceholder: boolean;
  onEventKeyDown?: (event: GridEvent) => void;
  onEventMouseDown?: (e: MouseEvent, event: GridEvent) => void;
  onMouseEnter?: (e: MouseEvent<HTMLDivElement>) => void;
  onMouseLeave?: (e: MouseEvent<HTMLDivElement>) => void;
  onScalerMouseDown?: (
    event: GridEvent,
    e: MouseEvent,
    dateToChange: "startDate" | "endDate",
  ) => void;
  position: EventPosition;
}
